from solution import longest_subseq_with_diff_one


def test_issue_example():
    """Example longest subsequence with adjacent difference one has length 6."""
    assert longest_subseq_with_diff_one([1, 2, 3, 4, 5, 3, 2], 7) == 6  # 7 - 1 = 6


def test_issue_empty_array():
    """Longest subsequence with adjacent difference one of empty array is 0."""
    assert longest_subseq_with_diff_one([], 0) == 0  # 0 + 0 = 0


def test_issue_single_element():
    """Longest subsequence with adjacent difference one of one element is 1."""
    assert longest_subseq_with_diff_one([5], 1) == 1  # 0 + 1 = 1


def test_issue_all_equal_values():
    """Longest subsequence with adjacent difference one of equal values is 1."""
    assert longest_subseq_with_diff_one([7, 7, 7], 3) == 1  # 0 + 1 = 1


def test_issue_consecutive_increasing():
    """Longest subsequence with adjacent difference one of [1,2,3,4] is 4."""
    assert longest_subseq_with_diff_one([1, 2, 3, 4], 4) == 4  # 3 + 1 = 4


def test_issue_noncontiguous_beats_contiguous():
    """Longest subsequence with adjacent difference one need not be contiguous."""
    assert longest_subseq_with_diff_one([1, 10, 2, 10, 3], 5) == 3  # 2 + 1 = 3


def test_issue_no_adjacent_difference_one():
    """Longest subsequence with adjacent difference one with no valid pair is 1."""
    assert longest_subseq_with_diff_one([1, 3, 5, 7], 4) == 1  # 0 + 1 = 1


def test_issue_duplicates_cannot_chain():
    """Longest subsequence with adjacent difference one cannot chain equal values."""
    assert longest_subseq_with_diff_one([1, 1, 2, 2, 3], 5) == 3  # 2 + 1 = 3


def test_contract_decreasing_sequence():
    """Difference of one includes decreasing adjacents, so [4,3,2,1] gives 4."""
    assert longest_subseq_with_diff_one([4, 3, 2, 1], 4) == 4  # 3 + 1 = 4


def test_contract_negative_numbers():
    """Difference of one applies to negative integers, so [-2,-1,0,1] gives 4."""
    assert longest_subseq_with_diff_one([-2, -1, 0, 1], 4) == 4  # 3 + 1 = 4


def test_contract_skip_middle_value():
    """Subsequence may skip a middle value to keep adjacent difference one."""
    assert longest_subseq_with_diff_one([1, 2, 3, 10, 4, 5], 6) == 5  # 6 - 1 = 5
